const escapeRegex = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const compileTemplateTranslations = (source: Record<string, TranslationRow>) =>
  Object.entries(source)
    .filter(([template]) => template.includes("{{"))
    .map(([template, row]) => {
    const names: string[] = [];
    const token = /\{\{(\w+)\}\}/g;
    let pattern = "";
    let last = 0;
    let match: RegExpExecArray | null;
    while ((match = token.exec(template))) {
      pattern += escapeRegex(template.slice(last, match.index)) + "([\\s\\S]+?)";
      names.push(match[1]);
      last = match.index + match[0].length;
    }
    pattern += escapeRegex(template.slice(last));
      return { regex: new RegExp(`^${pattern}$`), names, row };
    });
const TEMPLATE_TRANSLATIONS = compileTemplateTranslations(EXTENDED_TRANSLATIONS);

