const ACTIVE_APP_TEMPLATE_TRANSLATIONS = compileTemplateTranslations(ACTIVE_APP_TRANSLATIONS);

export function getTranslation(key: string, lang: LanguageCode): string {
  if (TRANSLATIONS[key] && TRANSLATIONS[key][lang]) {
    return TRANSLATIONS[key][lang];
  }
  const activeRow = ACTIVE_APP_TRANSLATIONS[key];
  if (activeRow) return activeRow[LANGUAGE_ORDER.indexOf(lang)] ?? key;
  const row = EXTENDED_TRANSLATIONS[key];
  if (row) return row[LANGUAGE_ORDER.indexOf(lang)] ?? key;
  const languageIndex = LANGUAGE_ORDER.indexOf(lang);
  for (const entry of [...TEMPLATE_TRANSLATIONS, ...ACTIVE_APP_TEMPLATE_TRANSLATIONS]) {
    const match = key.match(entry.regex);
    if (!match) continue;
    const translated = entry.row[languageIndex] ?? key;
    return translated.replace(/\{\{(\w+)\}\}/g, (_token, name: string) => {
      const captureIndex = entry.names.indexOf(name);
      return captureIndex >= 0 ? match[captureIndex + 1] : `{{${name}}}`;
    });
  }
  return key;
}
